call.result:
{
  "status": "ok",
  "files": [],
  "message": "Sterile Neutrino -> BBN / X-ray Bridge Server\n=============================================\n\nMaps sterile-neutrino particle parameters (m_s, sin^2 2theta, production mechanism) to what the particle PRODUCES \u2014 Delta N_eff, relic density, radiative decay line, free streaming \u2014 and to the BBN and X-ray constraints that follow.\n\nTOOLS:\n  describe_sterile_nu_tools      \u2014 this help\n  predict_sterile_nu             \u2014 one (m_s, theta) point, all observables\n  predict_sterile_nu_grid        \u2014 many points in one call (table + CSV)\n  check_sterile_nu_sbl_anomaly   \u2014 the BEST anomaly vs BBN and Planck\n  predict_sterile_nu_xray_line   \u2014 X-ray line flux, one or all targets\n  scan_sterile_nu_parameters     \u2014 (m_s, theta) plane scan -> CSV/NPZ + BBN limit\n  plot_sterile_nu_exclusion      \u2014 exclusion plane from a scan file\n  plot_sterile_nu_bbn_impact     \u2014 Yp, D/H vs N_eff with data bands\n  list_sterile_nu_skills / load_sterile_nu_skill \u2014 workflow recipes\n\nBBN: Yp, D/H, Li7 from a fit to the PRyMordial network (<0.3%); exclusion uses Delta chi^2 vs the SM > 3.84 (95%, 1 dof). Valid for m_s below ~100 keV (relativistic at BBN). For MeV+ masses decay injection is NOT modeled \u2014 results there are flagged and are not constraints.",
  "metadata": {
    "observations": {
      "Yp": {
        "value": 0.2449,
        "sigma": 0.004,
        "source": "Aver, Olive & Skillman, JCAP 07 (2021) 029"
      },
      "D_H": {
        "value": 2.547,
        "sigma": 0.025,
        "source": "Cooke, Pettini & Steidel, ApJ 855 (2018) 102"
      },
      "Neff_CMB": {
        "value": 2.99,
        "sigma": 0.17,
        "source": "Planck 2018 (TT,TE,EE+lowE+lensing+BAO)"
      },
      "Neff_CMB_S4": {
        "value": 3.044,
        "sigma": 0.03,
        "source": "CMB-S4 forecast"
      }
    },
    "bbn_fit_validity": {
      "neff": [
        2.044,
        6.044
      ],
      "omega_b_h2": [
        0.019,
        0.0257
      ],
      "tau_n": [
        866.4,
        890.4
      ]
    },
    "bbn_exclusion_rule": "delta_chi2_vs_sm > 3.84",
    "xray_limits_count": 10,
    "xray_targets": [
      "Perseus",
      "M31",
      "Milky_Way_center",
      "Coma",
      "stacked_galaxies"
    ],
    "sbl_best_experiment": {
      "delta_m2_eV2": 1.3,
      "sin2_2theta": 0.42,
      "source": "BEST experiment, PRL 128, 232501 (2022)",
      "status": "in tension with STEREO, PROSPECT, Daya Bay nulls"
    },
    "line_3p5_keV": {
      "E_keV": 3.55,
      "m_s_eV": 7100.0,
      "sin2_2theta_best": 7e-11,
      "sin2_2theta_range": [
        2e-11,
        2e-10
      ],
      "status": "debated",
      "refs": [
        "Bulbul+ (2014), ApJ 789, 13",
        "Boyarsky+ (2014), PRL 113, 251301",
        "Dessert+ (2020), Science 367, 1465 (exclusion)"
      ]
    }
  }
}

